insert into academy_tcf_listening.papers(id,version,content)
values('tcf-listening-04','tcf-listening-2026-11-test04-v2',$paper04v2${"id":"tcf-listening-04","version":"tcf-listening-2026-11-test04-v2","title":"TCF Listening · Test 04","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Une employée trie les ouvrages rendus sur un chariot près du comptoir.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. La bibliothécaire range des ouvrages sur un chariot. B. La bibliothécaire emprunte un livre à une étudiante. C. L'étudiante dépose des journaux devant la porte. D. L'étudiante cherche une place dans une salle de cours.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. La bibliothécaire range des ouvrages sur un chariot. B. La bibliothécaire emprunte un livre à une étudiante. C. L'étudiante dépose des journaux devant la porte. D. L'étudiante cherche une place dans une salle de cours."}],"audio":"q-01.mp3","audioSeconds":20.706,"slotSeconds":40,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'enseignant indique une grille d'horaires affichée au tableau de la classe.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. Les élèves installent du matériel dans une salle vide. B. Le professeur présente l'emploi du temps au tableau. C. Le professeur corrige des devoirs à son bureau. D. Les élèves passent une épreuve écrite sans professeur.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Les élèves installent du matériel dans une salle vide. B. Le professeur présente l'emploi du temps au tableau. C. Le professeur corrige des devoirs à son bureau. D. Les élèves passent une épreuve écrite sans professeur."}],"audio":"q-02.mp3","audioSeconds":20.683,"slotSeconds":40,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'étudiante utilise son téléphone devant un lecteur de contrôle à l'entrée.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. L'élève vérifie une note sur le tableau d'affichage. B. L'élève remplit une fiche à la réception. C. L'élève achète un ticket auprès du concierge. D. L'élève présente un code pour accéder au bâtiment.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. L'élève vérifie une note sur le tableau d'affichage. B. L'élève remplit une fiche à la réception. C. L'élève achète un ticket auprès du concierge. D. L'élève présente un code pour accéder au bâtiment."}],"audio":"q-03.mp3","audioSeconds":19.94,"slotSeconds":40,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'enfant rend un livre en présence d'un adulte au comptoir de la médiathèque.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Un parent lit un conte au groupe d'enfants. B. Une enseignante écrit sur un tableau avec un enfant. C. Un enfant remet un livre au guichet avec un parent. D. Un enfant choisit un livre sur une étagère.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Un parent lit un conte au groupe d'enfants. B. Une enseignante écrit sur un tableau avec un enfant. C. Un enfant remet un livre au guichet avec un parent. D. Un enfant choisit un livre sur une étagère."}],"audio":"q-04.mp3","audioSeconds":19.594,"slotSeconds":40,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La première réponse donne un emplacement plutôt qu'une durée ou des intervenants.","transcript":"Question 5.\nLe cours de conversation a lieu dans quelle salle ?\nA. Depuis deux semaines, tous les mercredis. B. Dans la salle deux, juste après l'escalier. C. Pendant deux heures, après le déjeuner. D. Avec deux intervenantes, dont une invitée.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Le cours de conversation a lieu dans quelle salle ?"},{"voice":"male","text":"A. Depuis deux semaines, tous les mercredis. B. Dans la salle deux, juste après l'escalier. C. Pendant deux heures, après le déjeuner. D. Avec deux intervenantes, dont une invitée."}],"audio":"q-05.mp3","audioSeconds":19.598,"slotSeconds":40},{"number":6,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'envoi d'un lien de récupération répond à la perte d'identifiant.","transcript":"Question 6.\nJ'ai oublié mon identifiant pour consulter les exercices. Vous pouvez m'aider ?\nA. Vous pourrez obtenir des résultats en fin de séance. B. Les exercices restent ouverts toute la semaine. C. Je vais vous envoyer un lien de récupération. D. Les cours commencent demain à la même heure.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"J'ai oublié mon identifiant pour consulter les exercices. Vous pouvez m'aider ?"},{"voice":"female","text":"A. Vous pourrez obtenir des résultats en fin de séance. B. Les exercices restent ouverts toute la semaine. C. Je vais vous envoyer un lien de récupération. D. Les cours commencent demain à la même heure."}],"audio":"q-06.mp3","audioSeconds":21.664,"slotSeconds":42},{"number":7,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La troisième proposition répond directement au caractère obligatoire de l'inscription.","transcript":"Question 7.\nEst-ce que l'atelier de demain demande une inscription ?\nA. L'atelier se déroule près de la gare. B. Oui, les enseignants y participent aussi. C. L'atelier commencera à seize heures. D. Oui, il faut réserver une place en ligne.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"Est-ce que l'atelier de demain demande une inscription ?"},{"voice":"male","text":"A. L'atelier se déroule près de la gare. B. Oui, les enseignants y participent aussi. C. L'atelier commencera à seize heures. D. Oui, il faut réserver une place en ligne."}],"audio":"q-07.mp3","audioSeconds":19.586,"slotSeconds":40},{"number":8,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La dernière réponse clarifie que le dictionnaire ne peut pas sortir de la bibliothèque.","transcript":"Question 8.\nPuis-je emprunter ce dictionnaire jusqu'à la semaine prochaine ?\nA. Non, cet exemplaire doit rester sur place. B. Ce dictionnaire a été publié récemment. C. Ce dictionnaire se trouve au premier étage. D. Ce dictionnaire existe en version numérique.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"Puis-je emprunter ce dictionnaire jusqu'à la semaine prochaine ?"},{"voice":"female","text":"A. Non, cet exemplaire doit rester sur place. B. Ce dictionnaire a été publié récemment. C. Ce dictionnaire se trouve au premier étage. D. Ce dictionnaire existe en version numérique."}],"audio":"q-08.mp3","audioSeconds":19.377,"slotSeconds":40},{"number":9,"kind":"announcement","question":"Où les étudiants suivront-ils le cours de demain ?","options":["Au laboratoire trois, à neuf heures.","Au laboratoire trois, à dix heures.","Dans la salle dix-huit, à dix heures.","Dans la salle dix-huit, à neuf heures."],"correct":"A","explanation":"Seul le lieu change; la séance conserve son horaire de neuf heures.","transcript":"Question 9.\nLe cours de phonétique du groupe B prévu dans la salle dix-huit aura lieu demain au laboratoire trois, au rez-de-chaussée. Le projecteur de la salle habituelle est en réparation. L'horaire de neuf heures reste inchangé, et les étudiants doivent apporter leurs écouteurs.\nOù les étudiants suivront-ils le cours de demain ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Le cours de phonétique du groupe B prévu dans la salle dix-huit aura lieu demain au laboratoire trois, au rez-de-chaussée. Le projecteur de la salle habituelle est en réparation. L'horaire de neuf heures reste inchangé, et les étudiants doivent apporter leurs écouteurs."},{"voice":"female","text":"Où les étudiants suivront-ils le cours de demain ?"}],"audio":"q-09.mp3","audioSeconds":19.662,"slotSeconds":41},{"number":10,"kind":"dialogue","question":"Pourquoi l'étudiant ne peut-il pas rejoindre immédiatement le groupe ?","options":["Son dossier ne contient pas de photographie.","Il manque une validation de son établissement.","Le groupe a atteint sa capacité maximale.","La période d'inscription est déjà terminée."],"correct":"B","explanation":"La participation attend une autorisation officielle malgré un dossier complet.","transcript":"Question 10.\nJ'ai reçu le programme de sciences, mais mon nom n'apparaît pas sur la liste des participants.\nVotre dossier est complet, mais l'autorisation de votre établissement n'a pas encore été transmise.\nJe peux vous l'apporter demain.\nOui, nous garderons votre place jusqu'à vendredi. Ensuite, nous confirmerons l'inscription.\nPourquoi l'étudiant ne peut-il pas rejoindre immédiatement le groupe ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"J'ai reçu le programme de sciences, mais mon nom n'apparaît pas sur la liste des participants."},{"voice":"female","text":"Votre dossier est complet, mais l'autorisation de votre établissement n'a pas encore été transmise."},{"voice":"male","text":"Je peux vous l'apporter demain."},{"voice":"female","text":"Oui, nous garderons votre place jusqu'à vendredi. Ensuite, nous confirmerons l'inscription."},{"voice":"female","text":"Pourquoi l'étudiant ne peut-il pas rejoindre immédiatement le groupe ?"}],"audio":"q-10.mp3","audioSeconds":26.212,"slotSeconds":48},{"number":11,"kind":"announcement","question":"Comment doit-on proposer un sujet pour l'échange linguistique ?","options":["En écrivant une lettre au club lundi.","En appelant l'organisateur avant vendredi.","En remplissant un formulaire avant mercredi.","En proposant un sujet sur place le vendredi."],"correct":"C","explanation":"Les thèmes doivent être transmis par formulaire en ligne avant mercredi midi.","transcript":"Question 11.\nLe club des langues prépare une soirée d'échanges. Les participants pourront proposer un thème de discussion sur le formulaire du site, jusqu'à mercredi à midi. Les organisateurs choisiront ensuite quatre thèmes et enverront le programme vendredi. Il n'est pas nécessaire de téléphoner pour s'inscrire.\nComment doit-on proposer un sujet pour l'échange linguistique ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"Le club des langues prépare une soirée d'échanges. Les participants pourront proposer un thème de discussion sur le formulaire du site, jusqu'à mercredi à midi. Les organisateurs choisiront ensuite quatre thèmes et enverront le programme vendredi. Il n'est pas nécessaire de téléphoner pour s'inscrire."},{"voice":"female","text":"Comment doit-on proposer un sujet pour l'échange linguistique ?"}],"audio":"q-11.mp3","audioSeconds":25.513,"slotSeconds":47},{"number":12,"kind":"dialogue","question":"Quel changement la tutrice propose-t-elle ?","options":["Déplacer la séance du mardi au jeudi matin.","Annuler le tutorat jusqu'au mois suivant.","Conserver les deux séances dans la grande salle.","Se retrouver le vendredi dans une autre salle."],"correct":"D","explanation":"Ils choisissent le vendredi dans une salle près du secrétariat.","transcript":"Question 12.\nJe peux encore vous accompagner en mathématiques le mardi, mais je ne serai plus disponible le jeudi.\nJ'ai déjà un cours de musique le mardi. Est-ce possible de se voir le vendredi ?\nLe vendredi après-midi, oui, si nous utilisons la petite salle près du secrétariat.\nParfait. Je vais prévenir la personne qui coordonne les séances.\nQuel changement la tutrice propose-t-elle ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Je peux encore vous accompagner en mathématiques le mardi, mais je ne serai plus disponible le jeudi."},{"voice":"male","text":"J'ai déjà un cours de musique le mardi. Est-ce possible de se voir le vendredi ?"},{"voice":"female","text":"Le vendredi après-midi, oui, si nous utilisons la petite salle près du secrétariat."},{"voice":"male","text":"Parfait. Je vais prévenir la personne qui coordonne les séances."},{"voice":"female","text":"Quel changement la tutrice propose-t-elle ?"}],"audio":"q-12.mp3","audioSeconds":25.004,"slotSeconds":47},{"number":13,"kind":"announcement","question":"Quelle activité sera interrompue mardi ?","options":["Les expériences pratiques du groupe de troisième.","Les cours de langue donnés dans les salles ordinaires.","Les réunions des enseignants prévues le lundi.","Les séances de lecture organisées dans la bibliothèque."],"correct":"A","explanation":"Les expériences doivent attendre jeudi parce que le laboratoire est fermé mardi.","transcript":"Question 13.\nLe laboratoire de sciences restera accessible aux enseignants lundi et mercredi, mais il sera fermé aux classes mardi pour vérifier les installations électriques. Les travaux n'affectent pas la bibliothèque, où les ateliers de lecture auront lieu normalement. Les expériences du groupe de troisième sont reportées à jeudi.\nQuelle activité sera interrompue mardi ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Le laboratoire de sciences restera accessible aux enseignants lundi et mercredi, mais il sera fermé aux classes mardi pour vérifier les installations électriques. Les travaux n'affectent pas la bibliothèque, où les ateliers de lecture auront lieu normalement. Les expériences du groupe de troisième sont reportées à jeudi."},{"voice":"female","text":"Quelle activité sera interrompue mardi ?"}],"audio":"q-13.mp3","audioSeconds":21.717,"slotSeconds":43},{"number":14,"kind":"dialogue","question":"Quelle solution le professeur retient-il pour la séance ?","options":["Donner le même enregistrement sans aucun équipement.","Remplacer définitivement l'écoute par de la grammaire.","Déplacer tous les étudiants vers le laboratoire réservé.","Répartir les étudiants en deux groupes successifs."],"correct":"D","explanation":"Ils utiliseront la petite salle en deux groupes, avec une autre tâche pour l'attente.","transcript":"Question 14.\nLe haut-parleur de la salle ne fonctionne plus. Nous avons un exercice d'écoute dans dix minutes.\nLe laboratoire audio est occupé, mais j'ai réservé une petite salle avec huit ordinateurs.\nNous avons douze étudiants.\nOn pourrait les répartir en deux groupes et faire l'activité l'un après l'autre.\nD'accord, je prépare une tâche de lecture pour ceux qui attendent.\nQuelle solution le professeur retient-il pour la séance ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le haut-parleur de la salle ne fonctionne plus. Nous avons un exercice d'écoute dans dix minutes."},{"voice":"female","text":"Le laboratoire audio est occupé, mais j'ai réservé une petite salle avec huit ordinateurs."},{"voice":"male","text":"Nous avons douze étudiants."},{"voice":"female","text":"On pourrait les répartir en deux groupes et faire l'activité l'un après l'autre."},{"voice":"male","text":"D'accord, je prépare une tâche de lecture pour ceux qui attendent."},{"voice":"female","text":"Quelle solution le professeur retient-il pour la séance ?"}],"audio":"q-14.mp3","audioSeconds":29.614,"slotSeconds":52},{"number":15,"kind":"radio-news","question":"Quelle difficulté accompagne le lancement des cours du soir ?","options":["Le coût des cours dépasse les prévisions de l'université.","Les adultes n'ont pas accès aux formations en bureautique.","Le retour après les cours reste difficile pour certains inscrits.","Les cours doivent être déplacés faute d'enseignants."],"correct":"C","explanation":"La demande existe, mais l'accès au transport en fin de soirée demeure compliqué.","transcript":"Question 15.\nÀ Rennes, une université populaire ouvre trois nouveaux cours du soir à destination des adultes en emploi. Les inscriptions sont nombreuses, notamment pour la bureautique et les langues. Toutefois, plusieurs candidats regrettent le manque de transports collectifs après vingt-deux heures. L'établissement discute avec la métropole d'une correspondance supplémentaire, sans annoncer encore de calendrier.\nQuelle difficulté accompagne le lancement des cours du soir ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"À Rennes, une université populaire ouvre trois nouveaux cours du soir à destination des adultes en emploi. Les inscriptions sont nombreuses, notamment pour la bureautique et les langues. Toutefois, plusieurs candidats regrettent le manque de transports collectifs après vingt-deux heures. L'établissement discute avec la métropole d'une correspondance supplémentaire, sans annoncer encore de calendrier."},{"voice":"female","text":"Quelle difficulté accompagne le lancement des cours du soir ?"}],"audio":"q-15.mp3","audioSeconds":28.88,"slotSeconds":51},{"number":16,"kind":"dialogue","question":"Pourquoi les enseignants échangent-ils leurs créneaux ?","options":["Pour participer à une réunion pédagogique mardi.","Pour permettre à un enseignant de siéger à un jury.","Pour modifier les horaires des évaluations des élèves.","Pour transférer les deux groupes dans le même bâtiment."],"correct":"B","explanation":"Un enseignant doit remplacer un collègue dans un jury d'examen jeudi.","transcript":"Question 16.\nJe peux prendre ton groupe jeudi matin si tu veux. J'ai terminé les évaluations prévues.\nMerci. Un jury d'examen m'a demandé de remplacer un collègue absent à cette heure-là.\nOn intervertira nos séances : tu prendras mon groupe mardi et je garderai le tien jeudi.\nJe préviendrai les étudiants, les salles ne changent pas.\nPourquoi les enseignants échangent-ils leurs créneaux ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Je peux prendre ton groupe jeudi matin si tu veux. J'ai terminé les évaluations prévues."},{"voice":"male","text":"Merci. Un jury d'examen m'a demandé de remplacer un collègue absent à cette heure-là."},{"voice":"female","text":"On intervertira nos séances : tu prendras mon groupe mardi et je garderai le tien jeudi."},{"voice":"male","text":"Je préviendrai les étudiants, les salles ne changent pas."},{"voice":"female","text":"Pourquoi les enseignants échangent-ils leurs créneaux ?"}],"audio":"q-16.mp3","audioSeconds":25.945,"slotSeconds":48},{"number":17,"kind":"announcement","question":"Que faut-il présenter pour créer une carte de bibliothèque ?","options":["Une attestation scolaire et un ancien abonnement.","Une pièce d'identité et un justificatif de domicile.","Un formulaire médical et une photographie récente.","Une carte d'étudiant et un bulletin de notes."],"correct":"B","explanation":"Les deux documents requis sont l'identité et le justificatif d'adresse.","transcript":"Question 17.\nLa médiathèque accueillera les nouveaux inscrits samedi. Pour établir une carte, apportez un justificatif de domicile récent et une pièce d'identité. Aucun certificat scolaire n'est demandé. Les personnes ayant déjà une carte peuvent simplement la présenter au guichet pour prolonger leur abonnement.\nQue faut-il présenter pour créer une carte de bibliothèque ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"La médiathèque accueillera les nouveaux inscrits samedi. Pour établir une carte, apportez un justificatif de domicile récent et une pièce d'identité. Aucun certificat scolaire n'est demandé. Les personnes ayant déjà une carte peuvent simplement la présenter au guichet pour prolonger leur abonnement."},{"voice":"female","text":"Que faut-il présenter pour créer une carte de bibliothèque ?"}],"audio":"q-17.mp3","audioSeconds":25.583,"slotSeconds":48},{"number":18,"kind":"telephone","question":"Pourquoi la personne préfère-t-elle une autre formation ?","options":["Elle veut terminer sa formation avant le lundi suivant.","Elle souhaite éviter les cours organisés en petit groupe.","Elle préfère un programme qui comporte moins d'exercices.","Elle cherche une session compatible avec son emploi."],"correct":"D","explanation":"Son travail l'empêche d'assister au programme en semaine.","transcript":"Question 18.\nBonjour, je m'intéresse à votre formation informatique de vingt heures.\nElle commence lundi et se déroule du lundi au jeudi, de neuf à quinze heures.\nJe travaille à ces horaires. Votre brochure mentionne aussi une session répartie sur quatre samedis.\nOui, elle reprend les mêmes objectifs, mais les exercices se font en petit groupe.\nDans ce cas, inscrivez-moi à celle du samedi, s'il reste une place.\nPourquoi la personne préfère-t-elle une autre formation ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"female","text":"Bonjour, je m'intéresse à votre formation informatique de vingt heures."},{"voice":"male","text":"Elle commence lundi et se déroule du lundi au jeudi, de neuf à quinze heures."},{"voice":"female","text":"Je travaille à ces horaires. Votre brochure mentionne aussi une session répartie sur quatre samedis."},{"voice":"male","text":"Oui, elle reprend les mêmes objectifs, mais les exercices se font en petit groupe."},{"voice":"female","text":"Dans ce cas, inscrivez-moi à celle du samedi, s'il reste une place."},{"voice":"female","text":"Pourquoi la personne préfère-t-elle une autre formation ?"}],"audio":"q-18.mp3","audioSeconds":32.122,"slotSeconds":55},{"number":19,"kind":"announcement","question":"Pourquoi les ateliers de lecture ont-ils moins de places ?","options":["Pour supprimer les ateliers proposés le mercredi.","Pour empêcher les parents de rester à proximité.","Pour laisser plus de temps à chaque enfant.","Pour réserver les séances aux lecteurs avancés."],"correct":"C","explanation":"L'effectif réduit permet un meilleur accompagnement individuel.","transcript":"Question 19.\nPendant les vacances, les ateliers de lecture pour les enfants seront limités à dix participants. Le personnel souhaite consacrer davantage de temps à chaque lecteur, notamment à ceux qui découvrent encore les sons et les lettres. Les parents pourront rester dans l'espace voisin. Les séances supplémentaires du mercredi permettront d'accueillir davantage de familles.\nPourquoi les ateliers de lecture ont-ils moins de places ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pendant les vacances, les ateliers de lecture pour les enfants seront limités à dix participants. Le personnel souhaite consacrer davantage de temps à chaque lecteur, notamment à ceux qui découvrent encore les sons et les lettres. Les parents pourront rester dans l'espace voisin. Les séances supplémentaires du mercredi permettront d'accueillir davantage de familles."},{"voice":"female","text":"Pourquoi les ateliers de lecture ont-ils moins de places ?"}],"audio":"q-19.mp3","audioSeconds":24.259,"slotSeconds":48},{"number":20,"kind":"dialogue","question":"Qu'est-ce qui préoccupe surtout l'apprenant ?","options":["L'absence d'équipement personnel pour suivre les activités.","Le manque d'échanges avec les enseignants du cours.","Le niveau de difficulté de tous les exercices proposés.","L'impossibilité de rendre ses devoirs avant la date prévue."],"correct":"A","explanation":"L'apprenant dispose d'un seul téléphone partagé et n'a pas d'ordinateur.","transcript":"Question 20.\nJ'aime bien les exercices en ligne, mais je n'arrive pas à télécharger les documents de la leçon.\nVotre connexion fonctionne-t-elle normalement ?\nPas toujours. Je partage un seul téléphone avec ma famille et je n'ai pas d'ordinateur chez moi.\nJe peux vous préparer une version imprimée, et la bibliothèque prête des ordinateurs sur rendez-vous.\nCela m'aiderait à travailler régulièrement.\nQu'est-ce qui préoccupe surtout l'apprenant ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"J'aime bien les exercices en ligne, mais je n'arrive pas à télécharger les documents de la leçon."},{"voice":"female","text":"Votre connexion fonctionne-t-elle normalement ?"},{"voice":"male","text":"Pas toujours. Je partage un seul téléphone avec ma famille et je n'ai pas d'ordinateur chez moi."},{"voice":"female","text":"Je peux vous préparer une version imprimée, et la bibliothèque prête des ordinateurs sur rendez-vous."},{"voice":"male","text":"Cela m'aiderait à travailler régulièrement."},{"voice":"female","text":"Qu'est-ce qui préoccupe surtout l'apprenant ?"}],"audio":"q-20.mp3","audioSeconds":28.755,"slotSeconds":52},{"number":21,"kind":"announcement","question":"Pourquoi les bénévoles sont-ils invités à confirmer leurs créneaux ?","options":["Pour sélectionner les lecteurs les plus expérimentés.","Pour couvrir les séances moins bien dotées en bénévoles.","Pour reporter les séances prévues le mercredi.","Pour fixer les tarifs des ateliers proposés le vendredi."],"correct":"B","explanation":"La confirmation permet de renforcer les séances du vendredi où le personnel manque.","transcript":"Question 21.\nL'association Lire ensemble cherche des bénévoles pour ses ateliers d'aide à la lecture. Les séances du mercredi sont déjà bien couvertes, mais celles du vendredi en fin d'après-midi manquent d'accompagnateurs. Merci d'indiquer vos horaires possibles d'ici lundi. La responsable établira ensuite des groupes de deux, afin que personne n'anime une séance seul lors de sa première participation.\nPourquoi les bénévoles sont-ils invités à confirmer leurs créneaux ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"L'association Lire ensemble cherche des bénévoles pour ses ateliers d'aide à la lecture. Les séances du mercredi sont déjà bien couvertes, mais celles du vendredi en fin d'après-midi manquent d'accompagnateurs. Merci d'indiquer vos horaires possibles d'ici lundi. La responsable établira ensuite des groupes de deux, afin que personne n'anime une séance seul lors de sa première participation."},{"voice":"female","text":"Pourquoi les bénévoles sont-ils invités à confirmer leurs créneaux ?"}],"audio":"q-21.mp3","audioSeconds":27.463,"slotSeconds":51},{"number":22,"kind":"interview","question":"Quel aspect la formatrice considère-t-elle comme le plus important ?","options":["La réduction du nombre d'évaluations obligatoires.","La reconnaissance immédiate d'un nouveau diplôme professionnel.","L'accès à des exercices plus difficiles chaque semaine.","L'assurance retrouvée grâce aux échanges entre apprenants."],"correct":"D","explanation":"Elle met en avant la confiance acquise grâce au groupe.","transcript":"Question 22.\nVotre atelier réunit des adultes qui reprennent leurs études après plusieurs années. Que leur apportent surtout les rencontres en groupe ?\nCertains ont besoin de revoir des notions, mais le vrai changement se produit souvent lorsqu'ils osent poser une question devant d'autres personnes. Ils découvrent qu'ils ne sont pas seuls à avoir oublié une méthode ou à redouter une évaluation. Cette confiance les aide à poursuivre un parcours qui paraissait inaccessible. Un cahier d'exercices peut être utile, mais il ne remplace pas ce soutien entre apprenants.\nQuel aspect la formatrice considère-t-elle comme le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Votre atelier réunit des adultes qui reprennent leurs études après plusieurs années. Que leur apportent surtout les rencontres en groupe ?"},{"voice":"female","text":"Certains ont besoin de revoir des notions, mais le vrai changement se produit souvent lorsqu'ils osent poser une question devant d'autres personnes. Ils découvrent qu'ils ne sont pas seuls à avoir oublié une méthode ou à redouter une évaluation. Cette confiance les aide à poursuivre un parcours qui paraissait inaccessible. Un cahier d'exercices peut être utile, mais il ne remplace pas ce soutien entre apprenants."},{"voice":"female","text":"Quel aspect la formatrice considère-t-elle comme le plus important ?"}],"audio":"q-22.mp3","audioSeconds":36.282,"slotSeconds":60},{"number":23,"kind":"panel-discussion","question":"Quel compromis ressort de la discussion sur les devoirs ?","options":["Confier la correction des devoirs entièrement aux familles.","Maintenir une longue liste d'exercices obligatoires chaque soir.","Essayer des tâches courtes avec une aide accessible à l'école.","Interdire tout travail de révision en dehors de l'école."],"correct":"C","explanation":"Les participants retiennent des révisions brèves et une aide accessible sans surcharger les familles.","transcript":"Question 23.\nUne représentante de parents estime que les devoirs écrits prennent trop de temps aux familles.\nComme professeur, je comprends cette difficulté, mais je souhaite conserver une occasion de réviser les notions.\nLes enfants n'ont pas tous un adulte disponible pour les accompagner.\nNous pourrions proposer des exercices courts, commencés en classe, avec une permanence facultative pour terminer ce qui pose problème.\nSi les consignes sont claires et que la charge est limitée, ce serait un progrès.\nÉvaluons cette formule pendant un trimestre.\nQuel compromis ressort de la discussion sur les devoirs ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Une représentante de parents estime que les devoirs écrits prennent trop de temps aux familles."},{"voice":"male","text":"Comme professeur, je comprends cette difficulté, mais je souhaite conserver une occasion de réviser les notions."},{"voice":"female","text":"Les enfants n'ont pas tous un adulte disponible pour les accompagner."},{"voice":"male","text":"Nous pourrions proposer des exercices courts, commencés en classe, avec une permanence facultative pour terminer ce qui pose problème."},{"voice":"female","text":"Si les consignes sont claires et que la charge est limitée, ce serait un progrès."},{"voice":"male","text":"Évaluons cette formule pendant un trimestre."},{"voice":"female","text":"Quel compromis ressort de la discussion sur les devoirs ?"}],"audio":"q-23.mp3","audioSeconds":37.87,"slotSeconds":61},{"number":24,"kind":"interview","question":"Quelle faiblesse de l'enquête la chercheuse souligne-t-elle ?","options":["Les personnes ayant abandonné la formation ne sont pas représentées.","Les anciens participants ne peuvent plus répondre au questionnaire.","Les étudiants interrogés viennent de plusieurs établissements.","Les résultats ont été recueillis à plusieurs dates différentes."],"correct":"A","explanation":"L'étude ignore les personnes qui se sont arrêtées avant la fin.","transcript":"Question 24.\nVous avez interrogé les étudiants qui ont achevé leur formation et presque tous se disent satisfaits. Est-ce suffisant pour évaluer le programme ?\nNon, car ceux qui ont quitté les cours avant la fin sont précisément absents de nos résultats. Certains ont pu rencontrer des difficultés d'horaire, de transport ou de compréhension que nous ignorons encore. Nous allons les contacter, mais aussi comparer les progressions réelles aux attentes de départ. Une satisfaction élevée chez les diplômés ne dit pas à elle seule si le programme convient à tous les inscrits.\nQuelle faiblesse de l'enquête la chercheuse souligne-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Vous avez interrogé les étudiants qui ont achevé leur formation et presque tous se disent satisfaits. Est-ce suffisant pour évaluer le programme ?"},{"voice":"female","text":"Non, car ceux qui ont quitté les cours avant la fin sont précisément absents de nos résultats. Certains ont pu rencontrer des difficultés d'horaire, de transport ou de compréhension que nous ignorons encore. Nous allons les contacter, mais aussi comparer les progressions réelles aux attentes de départ. Une satisfaction élevée chez les diplômés ne dit pas à elle seule si le programme convient à tous les inscrits."},{"voice":"female","text":"Quelle faiblesse de l'enquête la chercheuse souligne-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":38.099,"slotSeconds":62},{"number":25,"kind":"television-report","question":"Quel obstacle le reportage met-il en évidence ?","options":["Les différences d'accès à Internet compliquent le travail à domicile.","Les tablettes ne fonctionnent pas dans les salles de classe.","Les élèves n'ont plus le droit de travailler sur papier.","Les enseignants refusent d'utiliser les nouveaux exercices."],"correct":"A","explanation":"L'accès numérique à la maison est inégal, ce qui rend les devoirs difficiles pour certains.","transcript":"Question 25.\nDans une école primaire d'Annecy, des tablettes ont été distribuées à toutes les classes. Les enseignants peuvent proposer des exercices adaptés à différents niveaux.\nMais plusieurs familles ne disposent pas de connexion stable à domicile, explique la directrice. Les devoirs numériques n'étaient donc pas accessibles à tous.\nL'école prête désormais des équipements et laisse les exercices disponibles sur papier. Les responsables souhaitent vérifier si les résultats s'améliorent réellement avant de commander davantage d'appareils.\nQuel obstacle le reportage met-il en évidence ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Dans une école primaire d'Annecy, des tablettes ont été distribuées à toutes les classes. Les enseignants peuvent proposer des exercices adaptés à différents niveaux."},{"voice":"male","text":"Mais plusieurs familles ne disposent pas de connexion stable à domicile, explique la directrice. Les devoirs numériques n'étaient donc pas accessibles à tous."},{"voice":"female","text":"L'école prête désormais des équipements et laisse les exercices disponibles sur papier. Les responsables souhaitent vérifier si les résultats s'améliorent réellement avant de commander davantage d'appareils."},{"voice":"female","text":"Quel obstacle le reportage met-il en évidence ?"}],"audio":"q-25.mp3","audioSeconds":36.114,"slotSeconds":61},{"number":26,"kind":"interview","question":"Pourquoi le responsable insiste-t-il sur le suivi des apprentis ?","options":["Parce que les entreprises n'ont aucun moyen d'évaluer la progression.","Parce que tous les apprentis quittent l'entreprise après leur contrat.","Parce que la qualité du parcours dépasse l'obtention du diplôme.","Parce que les diplômes doivent être supprimés de l'apprentissage."],"correct":"C","explanation":"Il considère l'accompagnement et les conditions de formation, pas uniquement le diplôme.","transcript":"Question 26.\nVotre entreprise recrute chaque année plusieurs apprentis. Pourquoi ne pas juger le dispositif uniquement à partir du diplôme obtenu ?\nLe diplôme est un repère, mais il ne raconte pas tout. Certains jeunes restent dans l'entreprise, d'autres trouvent un métier différent après avoir découvert leurs compétences. Nous devons regarder la qualité de l'accompagnement, les conditions de travail et la façon dont ils progressent. Un apprenti qui termine son contrat sans jamais obtenir de conseils peut être diplômé tout en ayant vécu une expérience difficile.\nPourquoi le responsable insiste-t-il sur le suivi des apprentis ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"female","text":"Votre entreprise recrute chaque année plusieurs apprentis. Pourquoi ne pas juger le dispositif uniquement à partir du diplôme obtenu ?"},{"voice":"male","text":"Le diplôme est un repère, mais il ne raconte pas tout. Certains jeunes restent dans l'entreprise, d'autres trouvent un métier différent après avoir découvert leurs compétences. Nous devons regarder la qualité de l'accompagnement, les conditions de travail et la façon dont ils progressent. Un apprenti qui termine son contrat sans jamais obtenir de conseils peut être diplômé tout en ayant vécu une expérience difficile."},{"voice":"female","text":"Pourquoi le responsable insiste-t-il sur le suivi des apprentis ?"}],"audio":"q-26.mp3","audioSeconds":39.26,"slotSeconds":64},{"number":27,"kind":"dialogue","question":"Comment les deux enseignants réorganisent-ils l'examen ?","options":["Regrouper les deux classes dans une seule salle.","Annuler l'enregistrement des oraux du premier groupe.","Décaler tous les oraux au vendredi matin.","Utiliser deux salles puis les échanger à midi."],"correct":"D","explanation":"Les enseignants utilisent deux salles avec un échange à midi pour bénéficier du matériel.","transcript":"Question 27.\nLes deux groupes de langues passent l'oral jeudi, mais nous avons réservé la même salle.\nJe peux commencer avec mon groupe à neuf heures dans la salle douze. Tu prendras la salle quinze à la même heure.\nLe matériel d'enregistrement est installé dans la salle douze.\nAlors échangeons nos salles à midi, quand mon groupe aura terminé. Les deux examens pourront se dérouler sans retard.\nParfait, j'envoie le nouveau plan aux étudiants.\nComment les deux enseignants réorganisent-ils l'examen ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"male","text":"Les deux groupes de langues passent l'oral jeudi, mais nous avons réservé la même salle."},{"voice":"female","text":"Je peux commencer avec mon groupe à neuf heures dans la salle douze. Tu prendras la salle quinze à la même heure."},{"voice":"male","text":"Le matériel d'enregistrement est installé dans la salle douze."},{"voice":"female","text":"Alors échangeons nos salles à midi, quand mon groupe aura terminé. Les deux examens pourront se dérouler sans retard."},{"voice":"male","text":"Parfait, j'envoie le nouveau plan aux étudiants."},{"voice":"female","text":"Comment les deux enseignants réorganisent-ils l'examen ?"}],"audio":"q-27.mp3","audioSeconds":33.719,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quel changement rendrait l'évaluation plus équitable selon l'experte ?","options":["Remplacer les connaissances par des exercices de rapidité.","Adapter le support sans réduire la compétence exigée.","Éliminer toute lecture des programmes scientifiques.","Accorder la même note à tous les étudiants inscrits."],"correct":"B","explanation":"L'experte veut rendre le support accessible tout en préservant l'objectif de mesure.","transcript":"Question 28.\nCertaines épreuves demandent de lire rapidement un long document avant de répondre. Pourquoi faudrait-il les adapter ?\nParce que nous devons distinguer la compétence réellement évaluée des obstacles liés au support. Si l'objectif est de vérifier un raisonnement scientifique, une lecture particulièrement difficile risque de pénaliser un élève qui connaît pourtant les notions. Cela ne signifie pas simplifier les questions pour tous. On peut proposer une présentation plus accessible ou un temps adapté, tout en conservant le même niveau d'exigence sur les connaissances.\nQuel changement rendrait l'évaluation plus équitable selon l'experte ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Certaines épreuves demandent de lire rapidement un long document avant de répondre. Pourquoi faudrait-il les adapter ?"},{"voice":"female","text":"Parce que nous devons distinguer la compétence réellement évaluée des obstacles liés au support. Si l'objectif est de vérifier un raisonnement scientifique, une lecture particulièrement difficile risque de pénaliser un élève qui connaît pourtant les notions. Cela ne signifie pas simplifier les questions pour tous. On peut proposer une présentation plus accessible ou un temps adapté, tout en conservant le même niveau d'exigence sur les connaissances."},{"voice":"female","text":"Quel changement rendrait l'évaluation plus équitable selon l'experte ?"}],"audio":"q-28.mp3","audioSeconds":39.917,"slotSeconds":64},{"number":29,"kind":"debate","question":"Sur quoi les deux invités s'opposent-ils principalement ?","options":["Le choix des plateformes utilisées pour les devoirs à distance.","La place des outils de détection dans la vérification des travaux.","La durée nécessaire pour corriger les examens de langue.","Le calendrier d'adoption des nouveaux manuels scolaires."],"correct":"B","explanation":"Le débat concerne le poids des logiciels de détection dans une décision disciplinaire.","transcript":"Question 29.\nLes enseignants utilisent de plus en plus des logiciels pour détecter les textes générés automatiquement. Est-ce une bonne solution ?\nIls peuvent nous alerter sur certains travaux suspects. Il serait irresponsable d'ignorer totalement ces indices.\nMais leurs résultats sont parfois erronés. Accuser un élève sur la seule base d'un score peut abîmer la confiance.\nNous devons alors demander des traces du travail, comme des brouillons, plutôt que de sanctionner immédiatement.\nD'accord pour vérifier, mais il faut aussi apprendre aux élèves à citer leurs sources et à expliquer leur démarche.\nSur quoi les deux invités s'opposent-ils principalement ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Les enseignants utilisent de plus en plus des logiciels pour détecter les textes générés automatiquement. Est-ce une bonne solution ?"},{"voice":"male","text":"Ils peuvent nous alerter sur certains travaux suspects. Il serait irresponsable d'ignorer totalement ces indices."},{"voice":"female","text":"Mais leurs résultats sont parfois erronés. Accuser un élève sur la seule base d'un score peut abîmer la confiance."},{"voice":"male","text":"Nous devons alors demander des traces du travail, comme des brouillons, plutôt que de sanctionner immédiatement."},{"voice":"female","text":"D'accord pour vérifier, mais il faut aussi apprendre aux élèves à citer leurs sources et à expliquer leur démarche."},{"voice":"female","text":"Sur quoi les deux invités s'opposent-ils principalement ?"}],"audio":"q-29.mp3","audioSeconds":39.787,"slotSeconds":64},{"number":30,"kind":"interview","question":"Pourquoi la responsable a-t-elle modifié les visites du musée ?","options":["Pour présenter des collections différentes selon les jours.","Pour éviter les échanges entre visiteurs de langues différentes.","Pour adapter les explications aux références des publics.","Pour limiter les visites aux personnes bilingues."],"correct":"C","explanation":"Les visites tiennent compte des références culturelles, au-delà d'une traduction littérale.","transcript":"Question 30.\nVotre musée propose désormais des parcours bilingues, mais ils ne sont pas tous de simples traductions. Pourquoi ?\nNous avons remarqué que les visiteurs ne connaissent pas nécessairement les mêmes références culturelles. Certains concepts demandent une explication supplémentaire, des exemples différents ou des images plus précises. Nous avons donc travaillé avec des médiateurs de plusieurs langues et consulté des familles. Notre objectif n'est pas de raconter deux histoires contradictoires, mais de rendre le même patrimoine compréhensible pour des publics divers.\nPourquoi la responsable a-t-elle modifié les visites du musée ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre musée propose désormais des parcours bilingues, mais ils ne sont pas tous de simples traductions. Pourquoi ?"},{"voice":"female","text":"Nous avons remarqué que les visiteurs ne connaissent pas nécessairement les mêmes références culturelles. Certains concepts demandent une explication supplémentaire, des exemples différents ou des images plus précises. Nous avons donc travaillé avec des médiateurs de plusieurs langues et consulté des familles. Notre objectif n'est pas de raconter deux histoires contradictoires, mais de rendre le même patrimoine compréhensible pour des publics divers."},{"voice":"female","text":"Pourquoi la responsable a-t-elle modifié les visites du musée ?"}],"audio":"q-30.mp3","audioSeconds":38.611,"slotSeconds":64},{"number":31,"kind":"academic-monologue","question":"Quel principe d'apprentissage la conférencière met-elle en avant ?","options":["Une révision très longue remplace toutes les activités de rappel.","L'apprentissage est meilleur quand tous les mots sont revus une seule fois.","Les listes de vocabulaire ne peuvent pas être apprises en groupe.","La mémorisation s'améliore en espaçant les reprises dans le temps."],"correct":"D","explanation":"L'exposé valorise les rappels espacés et répétés, avec prudence sur la généralisation.","transcript":"Question 31.\nUne étude compare deux façons d'apprendre du vocabulaire. Le premier groupe révise toutes les listes la veille du test. Le second travaille moins longtemps chaque jour, mais revient sur les mots à plusieurs reprises. Le deuxième groupe obtient un meilleur rappel un mois après l'évaluation. Ce résultat ne signifie pas que toute révision intensive est inutile. Il suggère plutôt que la répartition des séances et les occasions de retrouver une information dans la mémoire jouent un rôle important dans sa conservation. Il faudra cependant confirmer ces effets dans d'autres contextes d'apprentissage.\nQuel principe d'apprentissage la conférencière met-elle en avant ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Une étude compare deux façons d'apprendre du vocabulaire. Le premier groupe révise toutes les listes la veille du test. Le second travaille moins longtemps chaque jour, mais revient sur les mots à plusieurs reprises. Le deuxième groupe obtient un meilleur rappel un mois après l'évaluation. Ce résultat ne signifie pas que toute révision intensive est inutile. Il suggère plutôt que la répartition des séances et les occasions de retrouver une information dans la mémoire jouent un rôle important dans sa conservation. Il faudra cependant confirmer ces effets dans d'autres contextes d'apprentissage."},{"voice":"female","text":"Quel principe d'apprentissage la conférencière met-elle en avant ?"}],"audio":"q-31.mp3","audioSeconds":39.085,"slotSeconds":65},{"number":32,"kind":"interview","question":"Comment l'université devrait-elle utiliser le modèle de décrochage ?","options":["En proposant une aide sans transformer le score en jugement.","En supprimant les entretiens lorsque le modèle signale un risque.","En décidant automatiquement quels étudiants doivent quitter l'université.","En classant définitivement les étudiants selon leurs premières absences."],"correct":"A","explanation":"Le modèle doit déclencher un soutien non stigmatisant et être vérifié.","transcript":"Question 32.\nVotre équipe a développé un outil qui estime quels étudiants risquent d'interrompre leurs études. Faut-il contacter automatiquement ceux qui obtiennent un score élevé ?\nUn signal peut aider, mais ce modèle s'appuie sur des données incomplètes. Un étudiant peut manquer un cours pour travailler ou pour des raisons familiales. Nous devons vérifier la situation sans étiqueter les personnes comme incapables de réussir. L'outil devrait orienter une offre de soutien discrète, et ses erreurs doivent être étudiées régulièrement. Il ne doit jamais remplacer un entretien ou entraîner une sanction.\nComment l'université devrait-elle utiliser le modèle de décrochage ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Votre équipe a développé un outil qui estime quels étudiants risquent d'interrompre leurs études. Faut-il contacter automatiquement ceux qui obtiennent un score élevé ?"},{"voice":"female","text":"Un signal peut aider, mais ce modèle s'appuie sur des données incomplètes. Un étudiant peut manquer un cours pour travailler ou pour des raisons familiales. Nous devons vérifier la situation sans étiqueter les personnes comme incapables de réussir. L'outil devrait orienter une offre de soutien discrète, et ses erreurs doivent être étudiées régulièrement. Il ne doit jamais remplacer un entretien ou entraîner une sanction."},{"voice":"female","text":"Comment l'université devrait-elle utiliser le modèle de décrochage ?"}],"audio":"q-32.mp3","audioSeconds":39.597,"slotSeconds":65},{"number":33,"kind":"commentary","question":"Quelle réserve le chroniqueur formule-t-il à propos du succès annoncé ?","options":["Le taux d'inscription ne suffit pas à mesurer les acquis des élèves.","Les cours du soir sont toujours moins efficaces que ceux du matin.","La fréquentation ne devrait jamais être comptée par les établissements.","Les programmes de formation manquent systématiquement de candidats."],"correct":"A","explanation":"Il souhaite évaluer progression et abandon, pas seulement l'intérêt initial.","transcript":"Question 33.\nLe centre de formation annonce une hausse de trente pour cent des inscriptions et présente ce chiffre comme une victoire. Il témoigne sans doute d'un intérêt réel. Mais combien d'apprenants terminent le parcours ? Combien progressent sur les compétences prévues ? Et ceux qui ne peuvent venir que le soir disposent-ils du même accompagnement ? Le nombre d'inscriptions est un indicateur de demande; il ne suffit pas à juger de l'efficacité pédagogique. Avant de célébrer, regardons aussi les acquis et les abandons.\nQuelle réserve le chroniqueur formule-t-il à propos du succès annoncé ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"male","text":"Le centre de formation annonce une hausse de trente pour cent des inscriptions et présente ce chiffre comme une victoire. Il témoigne sans doute d'un intérêt réel. Mais combien d'apprenants terminent le parcours ? Combien progressent sur les compétences prévues ? Et ceux qui ne peuvent venir que le soir disposent-ils du même accompagnement ? Le nombre d'inscriptions est un indicateur de demande; il ne suffit pas à juger de l'efficacité pédagogique. Avant de célébrer, regardons aussi les acquis et les abandons."},{"voice":"female","text":"Quelle réserve le chroniqueur formule-t-il à propos du succès annoncé ?"}],"audio":"q-33.mp3","audioSeconds":38.017,"slotSeconds":64},{"number":34,"kind":"roundtable","question":"Quel accord se dégage à propos des outils numériques ?","options":["Rendre tous les devoirs obligatoirement numériques dès le trimestre.","Réserver les salles informatiques aux élèves des classes avancées.","Supprimer les exercices en ligne au profit du papier uniquement.","Offrir plusieurs modes d'accès et un lieu équipé à l'école."],"correct":"D","explanation":"Les interlocuteurs associent activités numériques, documents papier et accès à une salle équipée.","transcript":"Question 34.\nPlusieurs écoles proposent des devoirs exclusivement en ligne. Est-ce souhaitable ?\nLes enseignants gagnent du temps pour donner des retours rapides.\nLes parents signalent pourtant que certains foyers partagent un seul appareil ou n'ont pas une connexion fiable.\nNous pourrions conserver les activités interactives, mais proposer aussi une version imprimée des consignes.\nEt ouvrir la salle informatique après les cours pour les élèves qui en ont besoin.\nOui, évaluons les deux possibilités avant de retirer une solution.\nQuel accord se dégage à propos des outils numériques ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Plusieurs écoles proposent des devoirs exclusivement en ligne. Est-ce souhaitable ?"},{"voice":"male","text":"Les enseignants gagnent du temps pour donner des retours rapides."},{"voice":"female","text":"Les parents signalent pourtant que certains foyers partagent un seul appareil ou n'ont pas une connexion fiable."},{"voice":"male","text":"Nous pourrions conserver les activités interactives, mais proposer aussi une version imprimée des consignes."},{"voice":"female","text":"Et ouvrir la salle informatique après les cours pour les élèves qui en ont besoin."},{"voice":"male","text":"Oui, évaluons les deux possibilités avant de retirer une solution."},{"voice":"female","text":"Quel accord se dégage à propos des outils numériques ?"}],"audio":"q-34.mp3","audioSeconds":37.127,"slotSeconds":63},{"number":35,"kind":"interview","question":"Quelle idée le chercheur remet-il en cause ?","options":["Un logiciel peut ajuster les exercices selon certains résultats.","L'efficacité dépend aussi des interactions et des explications.","Un réglage automatique précis garantit à lui seul les progrès.","Les enseignants doivent pouvoir aider les élèves en difficulté."],"correct":"C","explanation":"Il conteste l'idée que l'adaptation logicielle suffise sans accompagnement.","transcript":"Question 35.\nVotre laboratoire étudie les logiciels qui adaptent les exercices au niveau de chaque élève. Pourquoi les résultats sont-ils moins bons dans certaines classes ?\nParce qu'une bonne adaptation automatique n'assure pas que l'élève comprend la consigne ou persévère. Un programme peut proposer le bon niveau de difficulté, mais si l'activité manque de sens ou si l'enseignant ne peut pas intervenir, l'apprentissage reste limité. Nous devons observer les échanges dans la classe et la qualité des explications, pas seulement la précision des calculs du logiciel.\nQuelle idée le chercheur remet-il en cause ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"female","text":"Votre laboratoire étudie les logiciels qui adaptent les exercices au niveau de chaque élève. Pourquoi les résultats sont-ils moins bons dans certaines classes ?"},{"voice":"male","text":"Parce qu'une bonne adaptation automatique n'assure pas que l'élève comprend la consigne ou persévère. Un programme peut proposer le bon niveau de difficulté, mais si l'activité manque de sens ou si l'enseignant ne peut pas intervenir, l'apprentissage reste limité. Nous devons observer les échanges dans la classe et la qualité des explications, pas seulement la précision des calculs du logiciel."},{"voice":"female","text":"Quelle idée le chercheur remet-il en cause ?"}],"audio":"q-35.mp3","audioSeconds":37.838,"slotSeconds":64},{"number":36,"kind":"interview","question":"À quelle condition la participation des élèves est-elle utile ?","options":["Quand seuls les délégués interviennent dans la discussion.","Quand les élèves peuvent proposer et discuter des solutions réelles.","Quand les avis ne servent qu'à classer des activités populaires.","Quand les décisions sont entièrement prises avant le vote."],"correct":"B","explanation":"La participation exige un échange réel, des alternatives et un retour motivé.","transcript":"Question 36.\nVotre collège consulte les élèves sur les activités proposées. Est-ce une forme de démocratie scolaire ?\nPas si nous leur demandons seulement de voter pour une décision déjà prise. Ils doivent connaître les contraintes, proposer des alternatives et recevoir une réponse argumentée quand leurs idées ne sont pas retenues. Il faut aussi veiller à entendre ceux qui parlent rarement en réunion. La participation devient éducative lorsqu'elle donne une réelle possibilité de discussion, plutôt qu'une simple photographie de la popularité d'une proposition.\nÀ quelle condition la participation des élèves est-elle utile ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre collège consulte les élèves sur les activités proposées. Est-ce une forme de démocratie scolaire ?"},{"voice":"female","text":"Pas si nous leur demandons seulement de voter pour une décision déjà prise. Ils doivent connaître les contraintes, proposer des alternatives et recevoir une réponse argumentée quand leurs idées ne sont pas retenues. Il faut aussi veiller à entendre ceux qui parlent rarement en réunion. La participation devient éducative lorsqu'elle donne une réelle possibilité de discussion, plutôt qu'une simple photographie de la popularité d'une proposition."},{"voice":"female","text":"À quelle condition la participation des élèves est-elle utile ?"}],"audio":"q-36.mp3","audioSeconds":36.851,"slotSeconds":63},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des avis divergents sur la réforme ?","options":["Les avis contraires prouvent que personne n'a respecté le nouveau calendrier.","Les témoignages les plus fréquents doivent être considérés comme seuls exacts.","Les divergences éclairent les conséquences variables selon les familles.","Les expériences individuelles remplacent toutes les données sur les horaires."],"correct":"C","explanation":"Elle relie les récits aux différences de situations et aux données vérifiables.","transcript":"Question 37.\nLes élèves, les familles et les enseignants racontent des expériences opposées du nouveau calendrier scolaire. Pourquoi ne pas choisir le récit le plus représentatif ?\nParce que les effets varient selon les contraintes. Une famille peut apprécier une sortie plus tôt, tandis qu'une autre doit payer une garde supplémentaire. Nous vérifions les horaires et les dépenses, mais nous conservons aussi ces situations particulières pour comprendre la répartition des bénéfices et des difficultés. Une moyenne ne fait pas disparaître les écarts. Elle gagne à être complétée par l'analyse des personnes qui se trouvent de part et d'autre.\nPourquoi la chercheuse conserve-t-elle des avis divergents sur la réforme ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Les élèves, les familles et les enseignants racontent des expériences opposées du nouveau calendrier scolaire. Pourquoi ne pas choisir le récit le plus représentatif ?"},{"voice":"female","text":"Parce que les effets varient selon les contraintes. Une famille peut apprécier une sortie plus tôt, tandis qu'une autre doit payer une garde supplémentaire. Nous vérifions les horaires et les dépenses, mais nous conservons aussi ces situations particulières pour comprendre la répartition des bénéfices et des difficultés. Une moyenne ne fait pas disparaître les écarts. Elle gagne à être complétée par l'analyse des personnes qui se trouvent de part et d'autre."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des avis divergents sur la réforme ?"}],"audio":"q-37.mp3","audioSeconds":42.059,"slotSeconds":69},{"number":38,"kind":"public-lecture","question":"Quel paradoxe la conférence met-elle en évidence ?","options":["Les élèves les plus autonomes sont toujours les premiers accompagnés.","Une forte demande peut dégrader la qualité de l'accompagnement.","La gratuité du programme rend les progrès scolaires automatiques.","Les inscriptions restent faibles lorsque l'aide concerne les devoirs."],"correct":"B","explanation":"L'affluence peut dépasser les moyens et réduire la qualité du suivi.","transcript":"Question 38.\nL'ouverture d'un programme de soutien scolaire gratuit a suscité un intérêt considérable. Pourtant, son succès peut le fragiliser. Lorsque les inscriptions dépassent la capacité d'accueil, les bénévoles disposent de moins de temps pour chaque élève; certains enfants qui ont les besoins les plus importants attendent plusieurs semaines. Annoncer un grand nombre de participants ne suffit donc pas à démontrer une amélioration de l'apprentissage. Il faut définir des priorités transparentes, préparer davantage de tuteurs et mesurer les progrès réels. Une initiative peut être populaire tout en échouant à offrir l'aide promise à ceux qui en ont le plus besoin.\nQuel paradoxe la conférence met-elle en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"L'ouverture d'un programme de soutien scolaire gratuit a suscité un intérêt considérable. Pourtant, son succès peut le fragiliser. Lorsque les inscriptions dépassent la capacité d'accueil, les bénévoles disposent de moins de temps pour chaque élève; certains enfants qui ont les besoins les plus importants attendent plusieurs semaines. Annoncer un grand nombre de participants ne suffit donc pas à démontrer une amélioration de l'apprentissage. Il faut définir des priorités transparentes, préparer davantage de tuteurs et mesurer les progrès réels. Une initiative peut être populaire tout en échouant à offrir l'aide promise à ceux qui en ont le plus besoin."},{"voice":"female","text":"Quel paradoxe la conférence met-elle en évidence ?"}],"audio":"q-38.mp3","audioSeconds":42.94,"slotSeconds":69},{"number":39,"kind":"interview","question":"Quelle mesure la responsable juge-t-elle indispensable pour durer ?","options":["Garantir le renouvellement et l'accompagnement des tuteurs.","Réduire les échanges entre les bénévoles et les enseignants.","Accueillir davantage d'élèves sans modifier l'organisation.","Limiter les rendez-vous aux semaines qui précèdent les examens."],"correct":"A","explanation":"Elle privilégie la formation, la relève et la stabilité du suivi.","transcript":"Question 39.\nVotre réseau de tutorat bénévole a aidé beaucoup d'élèves cette année. Pourquoi ne pas augmenter immédiatement le nombre d'inscriptions ?\nNous avons pu compter sur des étudiants très motivés, mais certains terminent leur formation ou quittent la ville. Nous devons former de nouveaux tuteurs, assurer le suivi des élèves lorsqu'un bénévole se retire et maintenir une coordination régulière avec les écoles. Sans cela, une expansion rapide créera des promesses impossibles à tenir. Il vaut mieux proposer une place stable à moins d'élèves que multiplier les inscriptions sans continuité pédagogique.\nQuelle mesure la responsable juge-t-elle indispensable pour durer ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre réseau de tutorat bénévole a aidé beaucoup d'élèves cette année. Pourquoi ne pas augmenter immédiatement le nombre d'inscriptions ?"},{"voice":"female","text":"Nous avons pu compter sur des étudiants très motivés, mais certains terminent leur formation ou quittent la ville. Nous devons former de nouveaux tuteurs, assurer le suivi des élèves lorsqu'un bénévole se retire et maintenir une coordination régulière avec les écoles. Sans cela, une expansion rapide créera des promesses impossibles à tenir. Il vaut mieux proposer une place stable à moins d'élèves que multiplier les inscriptions sans continuité pédagogique."},{"voice":"female","text":"Quelle mesure la responsable juge-t-elle indispensable pour durer ?"}],"audio":"q-39.mp3","audioSeconds":40.032,"slotSeconds":67}]}$paper04v2$::jsonb)
